let todos = [];
let nextId = 1;

// add (immutable: build a new array instead of changing the old one)
todos = [...todos, { id: nextId, text: "Read lesson", done: false }];
nextId += 1;

// toggle id 1
todos = todos.map((t) => (t.id === 1 ? { ...t, done: !t.done } : t));

// remove id 1
todos = todos.filter((t) => t.id !== 1);

const remaining = todos.filter((t) => !t.done).length;

const before = [{id:'a',done:false},{id:'b',done:true}];
const after = before.map(todo =>
  todo.id === 'a' ? {...todo, done:true} : todo
);
